    "description": "Projects, priorities, deadlines, and progress.",
    "difficulty": "Intermediate",
    "html": "<main>\n  <h1>Project desk</h1>\n  <p class=\"subtitle\">Keep projects moving, with priorities and deadlines.</p>\n  <form id=\"entry-form\">\n    <label for=\"title\">Task</label><input id=\"title\" required maxlength=\"120\" placeholder=\"What is the next action?\">\n    <label for=\"project\">Project</label><input id=\"project\" required maxlength=\"60\" placeholder=\"Website launch\">\n    <label for=\"priority\">Priority</label><select id=\"priority\"><option>Normal</option><option>High</option><option>Low</option></select>\n    <label for=\"due\">Due date</label><input id=\"due\" type=\"date\" required>\n    <button>Add task</button>\n  </form>\n  <p id=\"summary\" class=\"summary\"></p>\n  <div class=\"filters\"><button data-filter=\"all\" aria-pressed=\"true\">All</button><button data-filter=\"high\" aria-pressed=\"false\">High priority</button><button data-filter=\"overdue\" aria-pressed=\"false\">Overdue</button></div>\n  <section id=\"list\" aria-label=\"Project tasks\"></section>\n  <p id=\"feedback\" role=\"status\"></p><p id=\"save-note\">Sample records. Preview changes reset when you run code.</p>\n</main>",
    "logic": "let records = readSaved([{id:1,title:'Prepare the demo',project:'My first app',priority:'High',due:'2026-10-26',done:false}]);\nlet filter = 'all';\nconst list = document.querySelector('#list');\nfunction render() {\n  list.replaceChildren();\n  const today = new Date().toLocaleDateString('en-CA');\n  const visible = records.filter(r => filter === 'all' || (filter === 'high' ? r.priority === 'High' : !r.done && r.due < today)).sort((a,b)=>a.due.localeCompare(b.due));\n  document.querySelector('#summary').textContent = `${records.filter(r=>!r.done).length} remaining · ${records.filter(r=>r.done).length} completed`;\n  if (!visible.length) list.textContent = 'Nothing here yet. Add a task or change the filter.';\n  visible.forEach(r => {\n    const card = document.createElement('article');\n    card.className = r.done ? 'done' : '';\n    const title = document.createElement('strong'); title.textContent = r.title;\n    const details = document.createElement('p'); details.textContent = `${r.project} · ${r.priority} · Due ${r.due}`;\n    const actions = document.createElement('div'); actions.className = 'row';\n    const toggle = document.createElement('button'); toggle.textContent = r.done ? 'Mark active' : 'Complete';\n    toggle.onclick = () => { r.done = !r.done; saveRecords(records); render(); };\n    const remove = document.createElement('button'); remove.textContent = 'Delete';\n    remove.onclick = () => { records = records.filter(x=>x.id!==r.id); saveRecords(records); render(); };\n    actions.append(toggle, remove); card.append(title,details,actions); list.append(card);\n  });\n}\ndocument.querySelector('#entry-form').onsubmit = e => {\n  e.preventDefault(); const input = document.querySelector('#title'); const title = input.value.trim();\n  if (!title) { document.querySelector('#feedback').textContent='Enter a task first.'; return; }\n  const project = document.querySelector('#project').value.trim();\n  const due = document.querySelector('#due').value;\n  if (!project || !due) { document.querySelector('#feedback').textContent='Add a project and due date.'; return; }\n  records.push({id:Date.now(),title,project,due,priority:document.querySelector('#priority').value,done:false}); saveRecords(records); input.value=''; render();\n};\nrender();",
    "extras": "// Filters change the visible list without deleting any records.\ndocument.querySelectorAll('[data-filter]').forEach(button => {\n  button.onclick = () => {\n    filter = button.dataset.filter;\n    document.querySelectorAll('[data-filter]').forEach(b => b.setAttribute('aria-pressed', String(b===button)));\n    render();\n  };\n});",
    "task": "Add an Urgent priority in the HTML select, then update the high-priority filter to include it.",
    "css": " :root { --accent: #4934d4; }\n* { box-sizing: border-box; }\nbody { margin: 0; padding: 24px; font: 16px/1.5 Arial, sans-serif; background: #f5f6fb; color: #24243a; }\nmain { max-width: 720px; margin: auto; }\nh1 { font-size: 30px; letter-spacing: -1px; margin-bottom: 6px; }\n.subtitle, #save-note { color: #68697d; font-size: 13px; }\nform, .summary { padding: 18px; border: 1px solid #e1e2eb; border-radius: 12px; background: white; margin: 20px 0; }\nform { display: grid; gap: 10px; }\nlabel { font-size: 13px; font-weight: bold; }\ninput, select, button { font: inherit; padding: 10px; border: 1px solid #ddd; border-radius: 7px; width: 100%; }\nbutton { cursor: pointer; background: var(--accent); color: white; border: none; }\n.filters { display: flex; gap: 8px; margin: 18px 0; }\n.filters button { background: white; color: #24243a; border: 1px solid #ddd; }\n.filters button[aria-pressed=\"true\"] { color: var(--accent); border-color: var(--accent); }\narticle { background: white; padding: 16px; border-radius: 10px; margin-bottom: 10px; border: 1px solid #e1e2eb; }\narticle p { margin: 6px 0; }\n.row { display: flex; gap: 8px; margin-top: 10px; }\n.row button { font-size: 13px; }\n.done { opacity: .6; }\n.done strong { text-decoration: line-through; }\n#feedback { font-size: 13px; color: var(--accent); }\n",
    "storage": "// This recipe saves records in this browser, not on a server.\nconst STORE_KEY = 'recipe-tasks-v1';\nfunction readSaved(fallback) {\n  try {\n    const value = JSON.parse(localStorage.getItem(STORE_KEY));\n    return Array.isArray(value) ? value : fallback;\n  } catch { return fallback; }\n}\nfunction saveRecords(records) {\n  try {\n    localStorage.setItem(STORE_KEY, JSON.stringify(records));\n    document.querySelector('#save-note').textContent = 'Saved in this browser.';\n  } catch {\n    document.querySelector('#save-note').textContent = 'Saving is unavailable in this preview. Export your app to use browser storage.';\n  }\n}\n"
